// ============================================
// 静默登录探测标记存取（transient，prompt=none）
// ============================================
// 存的是该次探测 authorize 请求的 state 值，回调时用于匹配
// （只有 state 与标记一致才按"探测无会话"处理，防伪造回调）

export function saveSilentProbe(state: string, clientId?: string): void {
  _transient.set(buildKey(SILENT_PROBE_KEY, clientId), state);
}

export function getSilentProbe(clientId?: string): string | null {
  return _transient.get(buildKey(SILENT_PROBE_KEY, clientId));
}

export function removeSilentProbe(clientId?: string): void {
  _transient.remove(buildKey(SILENT_PROBE_KEY, clientId));
}

// ============================================
// 清理所有 SSO 数据
// ============================================

export function clearAllSsoData(clientId?: string): void {
  if (clientId) {
    removeTokenData(clientId);
    removeOAuthState(clientId);
    removeOAuthNonce(clientId);
    removeReturnUrl(clientId);
    removeLogoutState(clientId);
    removeSilentProbe(clientId);
    removePkceVerifier(clientId);
    // popup nonce 复用 verifier key 空间（`${clientId}_popup_nonce`）
    removePkceVerifier(`${clientId}_popup_nonce`);
    return;
  }

  removeTokenData();
  removeOAuthState();
  removeOAuthNonce();
  removeReturnUrl();
  removeLogoutState();
  removeSilentProbe();

  // 无参调用必须清理全部 client 级残留（token:<clientId>、oauth_state:<clientId>、
  // oidc_nonce:<clientId>、return_url:<clientId>、pkce_verifier_<clientId> 等）。
  // 枚举浏览器存储中所有带前缀的 key：从原生存储、临时数据存储与 token 存储同时移除，
  // 且访问存储属性本身也要 try/catch（沙箱 iframe 下会抛 SecurityError）。
  const stores: Storage[] = [];
  try {
    if (typeof sessionStorage !== "undefined") stores.push(sessionStorage);
  } catch {
    /* 存储不可用 */
  }
  try {
    if (typeof localStorage !== "undefined") stores.push(localStorage);
  } catch {
    /* 存储不可用 */
  }

  const abstractKeys = new Set<string>();
  for (const store of stores) {
    const keys: string[] = [];
    try {
      for (let i = 0; i < store.length; i++) {
        const key = store.key(i);
        if (key?.startsWith(STORAGE_PREFIX)) keys.push(key);
      }
    } catch {
      continue;
    }
    for (const key of keys) {
      abstractKeys.add(key.slice(STORAGE_PREFIX.length));
      try {
        store.removeItem(key);
      } catch {
        /* 忽略 */
      }
    }
  }

  // 适配器级枚举：覆盖自定义 TokenStorage / 内存 fallback 中的 client 级 key
  // （这些 key 不在浏览器存储中，仅靠上方枚举无法发现）
  for (const store of [_transient, _storage]) {
    try {
      for (const key of store.keys?.() ?? []) abstractKeys.add(key);
    } catch {
      /* 忽略自定义实现异常 */
    }
  }

  for (const key of abstractKeys) {
    _transient.remove(key);
    _storage.remove(key);
  }
}

/**
 * 清理指定 clientId 列表的 PKCE verifier
 *
 * 适用于非浏览器环境或已知 clientId 场景。
 */
export function clearVerifiersForClients(clientIds: string[]): void {
  for (const clientId of clientIds) {
    _transient.remove(VERIFIER_KEY_PREFIX + clientId);
  }
}
